(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const btns = Array.from(document.querySelectorAll('button')).filter(b => /Confirm\s*OTP/i.test((b.innerText||'').replace(/\s+/g,' ')));
  let clicked = 0;
  for (const b of btns) { if (b.offsetParent !== null) { b.click(); clicked++; break; } }
  await sleep(12000);
  return JSON.stringify({clicked, url: location.href});
})()
